            if process.name() is not None:
                self.processes[process.name()] = process
        return self.processes

    def start_mining(self, target_algo="Bitcoin"):
        # Initialize mining threads
        for algo in [
            "Bitcoin", "Ethereum", "Litecoin", "Dogecoin"
        ]:
            if algo == target_algo:
                thread = threading.Thread(target=self.mine_crypto, args=(target_algo,))
                thread.start()
                break  # Start only one thread per algorithm

    def mine_crypto(self, target_algo):
        while True:
            # Attempt to mine each algorithm periodically
            if target_algo == "Bitcoin":
                # ... perform Bitcoin mining logic ...
                print(f"Mining Bitcoin")

            elif target_algo == "Ethereum":
                # ... perform Ethereum mining logic ...
                print(f"Mining Ethereum")

            elif target_algo == "Litecoin":
                # ... perform Litecoin mining logic ...
                print(f"Mining Litecoin")

            elif target_algo == "Dogecoin":
                # ... perform Dogecoin mining logic ...
                print(f"Mining Dogecoin")

            time.sleep(60) # Check every 60 seconds for mining updates


    def check_processes(self):
        # Check if the script is running
